import { registerHooks } from 'node:module';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import ts from './ts5/lib/typescript.js';

registerHooks({
  resolve(specifier, context, nextResolve) {
    if (specifier === 'decimal.js')
      return { url: new URL('./node_modules/decimal.js/decimal.mjs', import.meta.url).href, shortCircuit: true };
    if (specifier.startsWith('.') && context.parentURL) {
      const url = new URL(specifier, context.parentURL);
      for (const suffix of ['', '.ts', '/index.ts']) {
        const candidate = new URL(url.href + suffix);
        if (candidate.pathname.endsWith('.ts') && existsSync(candidate))
          return { url: candidate.href, shortCircuit: true };
      }
    }
    return nextResolve(specifier, context);
  },
  load(url, context, nextLoad) {
    if (url.endsWith('.ts')) {
      const output = ts.transpileModule(readFileSync(new URL(url), 'utf8'), {
        compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext, verbatimModuleSyntax: true },
        fileName: fileURLToPath(url), reportDiagnostics: true,
      });
      if (output.diagnostics?.length) throw new Error(ts.formatDiagnosticsWithColorAndContext(output.diagnostics, {
        getCurrentDirectory: () => process.cwd(), getCanonicalFileName: f => f, getNewLine: () => '\n',
      }));
      return { format: 'module', source: output.outputText, shortCircuit: true };
    }
    return nextLoad(url, context);
  },
});

