import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

const root = resolve(process.argv[2] ?? '../m8e-calc');
const units = await import(pathToFileURL(resolve(root, 'src/units/index.ts')));
const model = await import(pathToFileURL(resolve(root, 'src/features/convert/model.ts')));
const baseline = process.argv.includes('--baseline');
let checks = 0;
const eq = (actual, expected) => { assert.deepEqual(actual, expected); checks++; };
const throws = (run, code) => { assert.throws(run, { code }); checks++; };
const cases = [['1 in to cm', '2.54'], ['1 in in cm', '2.54'], ['3 ft 4 in to cm', '101.6']];
const reproduced = [];
for (const locale of ['de', 'en']) {
  for (const [query, expected] of cases) {
    if (baseline) {
      const state = model.convertReducer(model.initialConvertState(), { type: 'query', text: query, locale });
      eq(state.error, 'E_UNIT_UNKNOWN');
      throws(() => units.parseQuery(query, locale), 'E_UNIT_UNKNOWN');
      reproduced.push({ query, locale, parser: 'E_UNIT_UNKNOWN', reducer: state.error });
    } else {
      const parsed = units.parseQuery(query, locale);
      eq(units.convert(parsed.value, parsed.fromId, parsed.toId).toString(), expected);
      const state = model.convertReducer(model.initialConvertState(), { type: 'query', text: query, locale });
      eq(state.error, null); eq(model.resultsFor(state).cm, expected);
    }
  }
}
if (baseline) {
  console.log(JSON.stringify({ mode: 'original', node: process.version, checks, reproduced }, null, 2));
  process.exit(0);
}
const registry = symbols => [{ id: 'test', names: { de: 'Test', en: 'Test' }, baseUnitId: 'u0',
  units: symbols.map((symbol, i) => ({ id: `u${i}`, symbol, names: { de: symbol, en: symbol }, aliases: [],
    system: 'other', source: 'Parser test definition', exact: true, conversion: { kind: 'linear', factor: String(i + 1) } })) }];
for (const locale of ['de', 'en']) {
  for (const [query, from, to] of [['1 in', 'in', undefined], ['3 ft 4 in', 'ft', undefined], ['5 km in mi','km','mi'], ['1 in -> cm','in','cm'], ['3 ft 4 in -> cm','ft','cm'], ['5 L/100 km to mpg US','L-100km','mpg-us'], ['2 m2 nach cm2','m2','cm2'], ['1 mA to MA','A-m','A-M']]) {
    const parsed = units.parseQuery(query, locale); eq(parsed.fromId, from); eq(parsed.toId, to);
  }
  const localized = units.parseQuery(`${locale === 'de' ? '1,5' : '1.5'} in TO cm`, locale);
  eq(units.convert(localized.value, localized.fromId, 'cm').toString(), '3.81');
  const temp = units.parseQuery('-40 °C to °F', locale);
  eq(units.convert(temp.value, temp.fromId, 'degF').toString(), '-40');
  for (const [query, code] of [['1 mA in ma','E_UNIT_AMBIGUOUS'], ['3 °C 4 °F to K','E_UNIT_COMPOUND'], ['3 ft -4 in to cm','E_UNIT_COMPOUND'], ['3 ft 4 s nach cm','E_UNIT_COMPOUND'], ['-1 K in °C','E_UNIT_DOMAIN'], ['0 L/100 km to mpg US','E_UNIT_DOMAIN']]) throws(() => units.parseQuery(query, locale), code);
  for (const query of ['1 in to cm to mm','1 in in cm nach mm','1 in -> cm to mm','1 in to cm -> mm','1 in -> cm → mm','2 km to ','2 km in kg']) {
    assert.throws(() => units.parseQuery(query, locale), units.UnitError); checks++;
  }
  const engine = units.createUnitsEngine(registry(['a','b','c','a in b','b to c']));
  for (const query of ['1 a in b to c', '1 a in b']) throws(() => engine.parseQuery(query, locale), 'E_UNIT_AMBIGUOUS');
  eq(engine.parseQuery('1 a in b -> c', locale).fromId, 'u3');
  eq(engine.parseQuery('1 a -> b to c', locale).toId, 'u4');
  const names = units.createUnitsEngine(registry(['m','mA','MA','m in ma','ma in m']));
  for (const query of ['1 m in ma','1 ma in m']) throws(() => names.parseQuery(query, locale), 'E_UNIT_AMBIGUOUS');
  const whole = units.createUnitsEngine(registry(['a','b','a in b','A IN B']));
  throws(() => whole.parseQuery('1 a In b', locale), 'E_UNIT_AMBIGUOUS');
  throws(() => units.parseQuery('1 in to cm to mm', locale), 'E_UNIT_QUERY');

  eq(units.parseQuery('1 in'.padEnd(4096), locale).fromId, 'in');
  throws(() => units.parseQuery('1 in'.padEnd(4097), locale), 'E_UNIT_QUERY');
  const atLimit = 'base' + ' in'.repeat(32) + ' end';
  const overLimit = 'base' + ' in'.repeat(33) + ' end';
  const bounded = units.createUnitsEngine(registry(['base', atLimit, overLimit]));
  eq(bounded.parseQuery(`1 ${atLimit}`, locale).fromId, 'u1');
  throws(() => bounded.parseQuery(`1 ${overLimit}`, locale), 'E_UNIT_QUERY');
  eq(bounded.parseQuery(`1 ${overLimit} -> base`, locale).fromId, 'u2');
  const accepted = model.convertReducer(model.initialConvertState(), { type: 'query', text: '1 in to cm', locale });
  for (const text of ['1 mA in ma', '1 in to cm to mm']) {
    const next = model.convertReducer(accepted, { type: 'query', text, locale });
    eq({ ...next, error: null }, accepted); eq(model.resultsFor(next), {});
  }
  eq(model.resultsFor(model.convertReducer(accepted, { type: 'query', text: '2 in', locale })).cm, '5.08');
  for (const feet of [0, 1, 3, 12, 999, 1000]) for (let inches = 0; inches < 12; inches++) for (const connector of ['in','to','nach','->','→']) {
    const parsed = units.parseQuery(`${feet} ft ${inches} in ${connector} cm`, locale);
    const actual = units.convert(parsed.value, parsed.fromId, 'cm');
    const want = units.convert(String((feet * 12 + inches) * 254), 'cm', 'cm').div(100);
    assert(actual.minus(want).abs().lte(want.abs().plus(1).mul('1e-65'))); checks++;
  }
}
console.log(JSON.stringify({ mode: 'current', node: process.version, checks, result: 'passed', note: 'Supplemental real-source parser/reducer probe; not Vitest, build or browser validation.' }, null, 2));

