const ts = require('./ts5/lib/typescript.js');
const fs = require('node:fs');
const cp = require('node:child_process');
const files = cp.execFileSync('git', ['diff', '--name-only', '0d088b8c890b6d0b8826ba6eba46645e4ee4ea0b', 'HEAD'], {encoding:'utf8'}).trim().split('\n').filter(f => /\.tsx?$/.test(f));
let diagnostics = [];
for (const file of files) {
  const output = ts.transpileModule(fs.readFileSync(file, 'utf8'), {fileName:file, reportDiagnostics:true,
    compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext,jsx:ts.JsxEmit.ReactJSX,verbatimModuleSyntax:true}});
  diagnostics.push(...(output.diagnostics ?? []));
}
console.log(JSON.stringify({typescript:ts.version,files,syntacticDiagnostics:diagnostics.length}));
if(diagnostics.length) process.exitCode = 1;
